SELECT COUNT(DISTINCT CASE WHEN p.status = 'failed' THEN p.order_id END) * 1.0 / COUNT(DISTINCT CASE WHEN p.status = 'captured' THEN p.order_id END) FROM payments p JOIN orders o USING (order_id) WHERE o.is_deleted = FALSE AND o.order_at >= TIMESTAMP '2024-04-01 00:00:00' AND o.order_at < TIMESTAMP '2024-05-01 00:00:00' AND p.order_id IN (SELECT order_id FROM payments WHERE status = 'captured')
